import {CODES,SEQUESTRATION,MEDICARE_SHARE,modifierIncrement,CF_2026_WITHOUT_ONE_YEAR_INCREASE,APCM_CODES,apcmFee} from './engine.mjs';
// Each policy event: a one-sentence summary, one or more "what changed" tables built from the data, and optional
// background (shown collapsed). Policy text never contains the practice's dollar amounts; the app adds those.
const FR_2027='https://public-inspection.federalregister.gov/2026-22743.pdf',CRS='https://www.everycrsreport.com/files/2023-11-14_R45106_736e9d27525242025e3ec29fb6254356108dd30f.html';
const LABEL={'99212':'Est. level 2','99213':'Est. level 3','99214':'Est. level 4','99215':'Est. level 5','99202':'New level 2','99203':'New level 3','99204':'New level 4','99205':'New level 5'};
const r2=n=>Number(n).toFixed(2),r4=n=>Number(n).toFixed(4),usd=n=>'$'+Number(n).toFixed(2),pct=n=>(n>0?'+':n<0?'−':'')+Math.abs(n*100).toFixed(2)+'%';
const arrow=(a,b,f=r2)=>a===b?{text:f(b),changed:false}:{text:`${f(a)} → ${f(b)}`,changed:true};
const cfOf=(data,year,track)=>data.annual.find(r=>r.year===year&&r.track===track&&r.code==='99213').cf;
// Table builders. Each returns {caption, head, rows (cells are strings or {text,changed}), note?}.
const TABLES={
 rvus(data,year){
  const rows=CODES.map(code=>{const a=data.rvus.find(r=>r.year===year-1&&r.code===code),b=data.rvus.find(r=>r.year===year&&r.code===code);return [`${code}<small>${LABEL[code]}</small>`,arrow(a.work,b.work),arrow(a.pe,b.pe),arrow(a.mp,b.mp),arrow(a.total,b.total)];});
  const f0=data.rvus.find(r=>r.year===year-1&&r.code==='99213').work_factor,f1=data.rvus.find(r=>r.year===year&&r.code==='99213').work_factor;
  return {caption:`RVUs per visit, ${year-1} → ${year}`,head:['Code','Work','Practice expense|PE','Malpractice|MP','Total'],rows,note:f0!==f1?(f1===1?`The separate work adjustment (× ${f0} in ${year-1}) ended in ${year}.`:`Published work RVUs. Payment used work × ${f1} in ${year}, a budget-neutrality adjustment.`):f1!==1?`Published work RVUs; payment used work × ${f1}.`:'Unchanged values are greyed out.'};
 },
 cf(data,year){const tracks=year>=2026?[['nonqp','Non-QP'],['qp','QP']]:[['nonqp','All clinicians']];return {caption:`Conversion factor, ${year-1} → ${year} ($ per RVU)`,head:['',String(year-1),String(year),'Change'],rows:tracks.map(([t,l])=>{const a=cfOf(data,year-1,t),b=cfOf(data,year,t);return [l,usd4(a),usd4(b),{text:pct(b/a-1),changed:true}];})};},
 cfRun(data){const rows=[];for(let y=2021;y<=2025;y++){const a=cfOf(data,y,'nonqp'),p=cfOf(data,y-1,'nonqp');rows.push([String(y),usd4(a),{text:pct(a/p-1),changed:true}]);}rows.push(['2021 → 2025','',{text:pct(cfOf(data,2025,'nonqp')/cfOf(data,2021,'nonqp')-1),changed:true}]);return {caption:'Conversion factor by year ($ per RVU)',head:['Year','Conversion factor','Change from prior year'],rows,note:'2024 is the average of two rates: 32.7442 to March 8 and 33.2875 from March 9.'};},
 cfSteps(data){const step=(t,u)=>{const a=cfOf(data,2026,t),m=CF_2026_WITHOUT_ONE_YEAR_INCREASE[t],b=cfOf(data,2027,t);return [usd4(a),usd4(m),u,'× 0.9988',{text:usd4(b),changed:true}];};return {caption:'How the 2027 conversion factor was set ($ per RVU)',head:['','2026','Without 2026’s 2.5%','2027 update','Budget neutrality','2027'],rows:[['Non-QP',...step('nonqp','× 1.0025')],['QP',...step('qp','× 1.0075')]],note:'CY 2027 final rule, Tables D-B1 and D-B2.'};},
 seq(data,year){const P={2013:[['Until March 31, 2013','0%','0%'],['From April 1, 2013','2%','1.6%']],2020:[['January 1 – April 30, 2020','2%','1.6%'],['May 1, 2020 – March 31, 2022','0% (paused)','0%']],2022:[['January 1 – March 31, 2022','0%','0%'],['April 1 – June 30, 2022','1%','0.8%'],['From July 1, 2022','2%','1.6%']]}[year];return {caption:'Sequestration cut by period',head:['Period','Cut to Medicare’s payment','Cut to the allowed amount'],rows:P.map(r=>[r[0],{text:r[1],changed:true},{text:r[2],changed:true}]),note:`Medicare pays 80% of the allowed amount, so a 2% cut to its payment is ${(2*MEDICARE_SHARE).toFixed(1)}% of the allowed amount. The model averages ${year} by day: ${(SEQUESTRATION[year]*MEDICARE_SHARE*100).toFixed(2)}% of the allowed amount for the year.`};},
 g2211(data,year,state){const t=state.qp&&year>=2026?'qp':'nonqp';return {caption:`G2211 with each visit, ${year}`,head:['Code','Visit fee','G2211 add-on','Add-on as % of visit'],rows:CODES.map(code=>{const a=data.annual.find(r=>r.year===year&&r.track===t&&r.code===code);return [`${code}<small>${LABEL[code]}</small>`,usd(a.base_fee),{text:usd(a.complexity_increment),changed:true},(a.complexity_increment/a.base_fee*100).toFixed(0)+'%'];}),note:'National amounts before sequestration. The add-on is the same at every level, so it is a larger share of lower-level visits.'};},
 b1b2(data,year,state){const t=state.qp?'qp':'nonqp';return {caption:`Complexity amount per visit, 2026 → 2027 (${t==='qp'?'QP':'non-QP'} rate)`,head:['Code','2026 G2211','2027 B1 (16%)','2027 B2 (32%)'],rows:CODES.map(code=>{const g=data.annual.find(r=>r.year===2026&&r.track===t&&r.code===code).complexity_increment;return [`${code}<small>${LABEL[code]}</small>`,usd(g),{text:usd(modifierIncrement(data,t,code,'B1')),changed:true},{text:usd(modifierIncrement(data,t,code,'B2')),changed:true}];}),note:'National amounts before sequestration. B2 requires MSSP or LEAD ACO participation.'};},
 apcm(data,year,state){if(!data.apcm)return null;const t=state.qp?'qp':'nonqp',L={G0556:'≤1 chronic condition',G0557:'2+ chronic conditions',G0558:'QMB + 2+ chronic conditions'};return {caption:`APCM payment per patient per month (${t==='qp'?'QP':'non-QP'} rate from 2026)`,head:['Code','2025','2026','2027'],rows:APCM_CODES.map(c=>[`${c}<small>${L[c]}</small>`,...[2025,2026,2027].map(y=>({text:usd(apcmFee(data,c,y,cfOf(data,y,t))),changed:y===2025}))]),note:'National amounts before sequestration; the 20% patient share is included.'};},
};
const usd4=n=>'$'+r4(n);
const POLICIES={
 1997:{title:'Work RVUs for office visits raised',summary:'The first five-year review raised work RVUs for most office visits, offset by a 0.917 budget-neutrality factor on work.',tables:['rvus'],background:['CMS reviews RVUs every five years. The 0.917 factor kept total Medicare spending unchanged by scaling down all work RVUs.'],url:'https://www.govinfo.gov/content/pkg/FR-1996-11-22/pdf/96-29558.pdf'},
 1999:{title:'Practice-expense RVUs begin moving to a resource basis',summary:'Practice-expense RVUs started shifting from historical charges to the resources used to provide care.',tables:['rvus'],background:['The 1999 blend was 75% charge-based and 25% resource-based, reaching 100% resource-based in 2002. The separate work adjustment also ended in 1999.'],url:'https://www.cms.gov/Regulations-and-Guidance/Guidance/Transmittals/Downloads/R1769B3.pdf'},
 2007:{title:'Work RVUs for office visits raised',summary:'The five-year review raised work RVUs for established office visits, offset by a 0.8994 budget-neutrality factor on work.',tables:['rvus'],background:['The adjustment reduced work RVUs only, not practice-expense or malpractice RVUs. In 2009 it moved into the conversion factor.'],url:'https://www.cms.gov/newsroom/press-releases/medicare-announces-final-rule-setting-physician-payment-rates-and-policies-2007'},
 '2013-sequestration':{title:'2% sequestration begins',summary:'From April 1, 2013, Medicare’s payment is cut 2%. The patient’s 20% share is not cut.',tables:['seq'],background:['Required by the Budget Control Act of 2011 and extended repeatedly, now through fiscal year 2032.'],url:CRS},
 '2020-sequestration':{title:'Sequestration paused',summary:'The 2% cut was suspended from May 1, 2020, during COVID-19, and stayed off through March 2022.',tables:['seq'],background:['Suspended by the CARES Act and extended by later laws. No sequestration applied in all of 2021.'],url:CRS},
 '2022-sequestration':{title:'Sequestration returns',summary:'The cut came back as 1% in April 2022 and the full 2% from July 2022.',tables:['seq'],background:['Set by the Protecting Medicare and American Farmers from Sequester Cuts Act. The full 2% has applied since, including in 2026 and 2027.'],url:CRS},
 2021:{title:'Office E/M visits revalued',summary:'Office visit RVUs rose substantially, and visit levels could now be chosen by medical decision-making or total time.',tables:['rvus'],background:['History and examination no longer determined the visit level. Because the change was budget neutral, the conversion factor fell for all services.'],url:'https://www.cms.gov/sites/default/files/2022-01/Physician_Fee_Schedule__PFS__Payment_for_OfficeOutpatient_Evaluation_and_Management__EM__Visits.pdf'},
 2024:{title:'G2211 add-on begins',summary:'G2211 became payable as a fixed add-on to office visits for ongoing or complex care.',tables:['g2211'],background:['It recognizes being the continuing focal point for a patient’s care, or managing a serious or complex condition over time. It could be added to new and established visits.'],url:'https://www.cms.gov/files/document/mm13473-how-use-office-and-outpatient-evaluation-and-management-visit-complexity-add-code-g2211.pdf'},
 '2025-apcm':{title:'APCM codes begin',summary:'Advanced Primary Care Management pays a set amount per patient per month, from January 2025.',tables:['apcm'],background:['The level depends on the patient: G0556 for one or fewer chronic conditions, G0557 for two or more, G0558 for a Qualified Medicare Beneficiary with two or more. Billed once per patient per month; consent is required and the 20% coinsurance generally applies.'],url:'https://www.cms.gov/medicare/payment/fee-schedules/physician-fee-schedule/advanced-primary-care-management-services'},
 2025:{title:'Conversion factor cut, fourth year in a row',summary:'The conversion factor fell every year from 2022 to 2025.',tables:['cfRun'],background:['Temporary increases set by Congress for 2021–2024 offset part of the cuts; none carried into 2025. Budget-neutrality offsets for the 2021 E/M revaluation and for G2211 also lowered the conversion factor.'],url:'https://www.cms.gov/files/document/cms-1807-f.pdf'},
 2026:{title:'Conversion factor up; office practice-expense RVUs up',summary:'The conversion factor rose, including a one-year 2.5% increase, and office practice-expense RVUs rose.',tables:['cf','rvus'],background:['QP and non-QP conversion factors differed for the first time. CMS began recognizing greater indirect practice costs for office-based than for facility-based practitioners. Office visits were exempt from the new 2.5% efficiency cut to work RVUs.'],url:'https://www.cms.gov/newsroom/fact-sheets/calendar-year-cy-2026-medicare-physician-fee-schedule-final-rule-cms-1832-f'},
 '2027-rvu':{title:'Office practice-expense RVUs down',summary:'Practice-expense RVUs fell for most office visit codes; work RVUs did not change.',tables:['rvus'],background:['The same rule changed how indirect practice costs are spread across services: CMS now allocates them using both work and clinical-labor RVUs for all services except 10- and 90-day global procedures.'],url:FR_2027},
 '2027-rate':{title:'2026’s one-time 2.5% increase expires',summary:'The conversion factor drops because 2026’s one-year increase ends. The 2027 update itself is slightly positive.',tables:['cfSteps'],background:['The 2.5% increase applied to 2026 only, by statute. The 2027 update is +0.25% for non-QPs and +0.75% for QPs, with a −0.12% budget-neutrality adjustment.'],url:FR_2027},
 2027:{title:'B1 and B2 replace G2211',summary:'The fixed G2211 add-on is replaced by modifiers worth 16% (B1) or 32% (B2) of the visit’s full fee.',tables:['b1b2'],background:['The CY 2027 final rule sets B1 at 16 percent of the total RVUs of the E/M service on the claim. B2, at 32 percent, is limited to clinicians in MSSP or LEAD ACOs; it does not depend on QP status.'],url:FR_2027},
};
export function policyFor(data,state,key){const policy=POLICIES[key];if(!policy)return null;const year=parseInt(key,10);const tables=policy.tables.map(t=>TABLES[t](data,year,state)).filter(Boolean);return {...policy,year,tables};}
export const POLICY_KEYS=Object.keys(POLICIES);
